int main() 
{
    // Open the text file 
    std::ifstream inputFile("word_count.txt");

    // Read each line of the file 
    std::string line; 
    while (std::getline(inputFile, line)) 
    {
        std::string word(line); 
        int count = 0;

        // Search for the word 
        for (int i = 0; i < line.length(); i++) 
        {
            if (line.substr(i, word.length()) == word) 
                count++;
        }

        // Print the result 
        std::cout << "Word: " << word << "\tNumber of occurrences: " << count << "\n"; 
    } 

    return 0;
}

