def longest_common_subsequence(s1, s2):
    # Create a dictionary of length 0 to store results 
    res = [None] * len(s1)

    # Initialize result for the empty string
    for i in range(len(s1)):
        res[i] = [None]

    # go through s1 and s2, and find the maximum length of common subsequence
    for i in range(len(s1)):
        for j in range(len(s2)):
            if s1[i] == s2[j]:
                # update result of current position
                res[i][j] = max(res[i][j-1] or 0, res[i-1][j]) + 1
                # update result of next position
                res[i+1][j] = max(res[i+1][j-1] or 0, res[i][j-1]) + 1

    # return result
    return res

