        if self.back is None:
            self.front = None
        else:
            self.back = self.back.next = item

    def dequeue(self):
        if self.front is None:
            raise Queue.Empty
        return self.front

    def __len__(self):
        return len(self.items)

    def is_empty(self):
        return self.front is None

    def push(self, item):
        self.enqueue(item)

    def pop(self):
        return self.dequeue()

    def peek(self):
        if not self.is_empty():
            return self.front
        else:
            return "Queue is empty"

