def findCommonElements(arr1, arr2):
    # create a dictionary to store the common elements
    common_elems = {}

    # loop through both arrays
    for i in range(len(arr1)):
        if arr1[i] in common_elems:
            common_elems[arr1[i]] += 1
        else:
            common_elems[arr1[i]] = 1

    # loop through arr2 and check for elements that are already in the dictionary
    for j in range(len(arr2)):
        if arr2[j] in common_elems:
            common_elems[arr2[j]] += 1
        else:
            common_elems[arr2[j]] = 1

    # return the common elements
    return common_elems

